// Generated by `cargo xtask grammar-fix`. Once green and you're
// happy with the grammar shape, move this into tests/ proper.
//
// Card           : Birds of Paradise
// Set            : lea
// Collector #    : 186

#[test]
fn round_trip() {
    let text = "Flying\n{T}: Add one mana of any color.";
    let ast = mtg_grammar::parse(text).expect("parse");
    let reprinted = mtg_grammar::unparse(&ast);
    let ast2 = mtg_grammar::parse(&reprinted).expect("reparse");
    assert_eq!(ast, ast2);
}
